export function speechReport(r,title){const c=r.context||{};return ['MIMORA — PRONUNCIATION REPORT',title,`Created: ${r.createdAt}`,`Target: ${c.phrase}`,`Language: ${c.language}`,`Method: ${r.version}`,`Model: ${r.provenance.model.id}@${r.provenance.model.revision}`,`Reference audio SHA-256: ${r.provenance.referenceHash}`,`Learner audio SHA-256: ${r.provenance.learnerHash}`,'',r.summary,...r.measurements.map(m=>`${m.label}: ${m.value}`),'','WHAT TO KEEP',...r.referenceGuide.map(x=>`${x.text} Expert ${x.reference[0].toFixed(2)} s; you ${x.learner[0].toFixed(2)} s.`),'','SOUND ALIGNMENT',...r.phoneRows.map(x=>`${x.reference?.symbol||'—'} → ${x.learner?.symbol||'—'} (${x.kind})`),'','CORRECTIONS TO REVIEW',...r.findings.flatMap(f=>[`${f.category} [${f.status}; ${f.review}]`,f.referenceDetail,f.learnerDetail,f.observation,`Practice: ${f.action}`,`Evidence: ${f.evidence}`,'']),'','LIMITATIONS',...r.limitations].join('\n');}
